$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$w='C:\Users\Administrator\WorkSpace\muxigame';$s="$w\bmc5server"
$mods=@(Get-ChildItem "$s\mods" -File -Filter *.jar|ForEach-Object{@{name=$_.Name;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower();size=$_.Length}})
$models=@(Get-ChildItem "$s\config\yes_steve_model\custom" -File -Recurse|Where-Object{$_.FullName -match 'umamusume|grounding|ground_'}|ForEach-Object{@{path=$_.FullName.Substring($s.Length+1);sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower();size=$_.Length}})
$start=@('start.bat','run.bat','start-muxi.ps1','tools\rcon.ps1')|ForEach-Object{@{path=$_;sha256=(Get-FileHash "$s\$_" -Algorithm SHA256).Hash.ToLower()}}
$groups=@('world','mods','config','libraries')|ForEach-Object{$files=@(Get-ChildItem "$s\$_" -File -Recurse -Force);@{name=$_;files=$files.Count;bytes=($files|Measure-Object Length -Sum).Sum}}
@{atUtc=[DateTime]::UtcNow.ToString('o');hostname=$env:COMPUTERNAME;mods=$mods;models=$models;startup=$start;storage=$groups;freeBytes=(Get-PSDrive C).Free;listeners=@(Get-NetTCPConnection -LocalPort 25565 -State Listen -ErrorAction SilentlyContinue|Select-Object OwningProcess);owners=@(Get-ChildItem "$w\.releases\release-owner.json" -ErrorAction SilentlyContinue|Select-Object Name,LastWriteTimeUtc);version='inspect-release-receipts';releaseDirectories=@(Get-ChildItem "$w\.releases" -Directory|Select-Object -ExpandProperty Name);workingRoot=$w;productionRoot=$s;listenerIdentity=@(Get-NetTCPConnection -LocalPort 25565 -State Listen -ErrorAction SilentlyContinue|Select-Object -ExpandProperty OwningProcess -Unique|ForEach-Object{$x=Get-CimInstance Win32_Process -Filter "ProcessId=$_";@{pid=$x.ProcessId;name=$x.Name;created=$x.CreationDate.ToUniversalTime().ToString('o');neoForgeArgs=($x.CommandLine -like '*neoforge*win_args.txt*')}})}|ConvertTo-Json -Depth 8 -Compress

